var i=`0166-spaghetti-alle-vongole`;var a=`world-0166`;var s=`IT`;var n=`southern-europe`;var r=4;var o=23;var l={en:`Spaghetti alle Vongole`,ua:`Спагеті з вонголе`};var g={en:`A classic dish from Italy, featuring garlic, clam, spaghetti, parsley. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Італія. Основні складники: часник, венерка, спагеті, петрушка. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var u=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 4 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 4 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:4,i:[[`garlic`,4,`clove`],[`extra-virgin-olive-oil`,50,`ml`],[`crushed-red-pepper`,3,`g`]]},{en:`Add the listed ingredients to the pot. Keep at a gentle simmer for about 6 minutes, until tender and cooked through.`,ua:`Додайте зазначені складники до каструлі. Варіть за слабкого кипіння приблизно 6 хвилин до м’якості та готовності.`,t:[`simmering`],m:6,i:[[`clam`,950,`g`],[`dry-white-wine`,160,`ml`]]},{en:`Cook the pasta in generously salted boiling water for about 10 minutes until al dente; reserve a cup of its starchy water.`,ua:`Варіть пасту в добре підсоленій киплячій воді приблизно 10 хвилин до стану аль денте; збережіть чашку крохмалистої води.`,t:[`pasta-boiling`],m:10,i:[[`spaghetti`,390,`g`],[`water`,1550,`ml`],[`table-salt`,8,`g`]]},{en:`Toss the cooked pasta with the sauce, adding a splash of reserved pasta water until everything is evenly coated.`,ua:`Змішайте готову пасту із соусом, додаючи потроху збережену воду з-під пасти, доки соус рівномірно вкриє її.`,t:[`pasta-finishing-in-sauce`,`tossing`],m:3,i:[[`parsley`,25,`g`]]}];var d={slug:i,id:a,country:`IT`,region:n,servings:4,minutes:23,title:l,text:g,steps:u};export{s as country,d as default,a as id,o as minutes,n as region,r as servings,i as slug,u as steps,g as text,l as title};